#include "protocol.h"
#define HEADER 9u
uint16_t mb_crc16(const uint8_t *p, size_t n) { uint16_t c=0xffff; while(n--) { c^=(uint16_t)*p++<<8; for(unsigned i=0;i<8;i++) c=(c&0x8000)?(uint16_t)((c<<1)^0x1021):(uint16_t)(c<<1); } return c; }
int mb_encode(const mb_frame_t *f,uint8_t *o,size_t cap,size_t *used) { if(!f||!o||!used||f->version!=MB_VERSION||f->length>MB_MAX_PAYLOAD||cap<HEADER+f->length+2)return -1; o[0]=f->version;o[1]=f->kind;o[2]=(uint8_t)f->node;o[3]=(uint8_t)(f->node>>8);for(int i=0;i<4;i++)o[4+i]=(uint8_t)(f->seq>>(8*i));o[8]=f->length;for(unsigned i=0;i<f->length;i++)o[9+i]=f->payload[i];uint16_t c=mb_crc16(o,HEADER+f->length);o[HEADER+f->length]=(uint8_t)c;o[HEADER+f->length+1]=(uint8_t)(c>>8);*used=HEADER+f->length+2;return 0; }
int mb_decode(const uint8_t *p,size_t n,mb_frame_t *f) { if(!p||!f||n<HEADER+2||p[0]!=MB_VERSION||p[8]>MB_MAX_PAYLOAD||n!=HEADER+p[8]+2)return -1;uint16_t c=mb_crc16(p,n-2), got=(uint16_t)p[n-2]|((uint16_t)p[n-1]<<8);if(c!=got)return -2;f->version=p[0];f->kind=p[1];f->node=(uint16_t)p[2]|((uint16_t)p[3]<<8);f->seq=(uint32_t)p[4]|((uint32_t)p[5]<<8)|((uint32_t)p[6]<<16)|((uint32_t)p[7]<<24);f->length=p[8];for(unsigned i=0;i<f->length;i++)f->payload[i]=p[9+i];f->crc=got;return 0;}
